import React, { useState, useEffect, useContext } from "react";
import { useParams, useNavigate } from "react-router-dom";
import axios from "axios";
import { OrderContext } from "./OrderContext";
import backgroundImage from "../Img/order3.jpg";

const UpdateOrder = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const { setOrdersChanged } = useContext(OrderContext);

  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [orderData, setOrderData] = useState({
    firstName: "",
    lastName: "",
    email: "",
    phoneNumber: "",
    address: "",
    city: "",
    orderId: "",
    specialInstructions: "",
    pickupTime: "",
    orderStatus: "",
  });

  const [allOrders, setAllOrders] = useState([]); // Store all orders

  // Fetch order details
  useEffect(() => {
    const fetchOrderDetails = async () => {
      try {
        const response = await axios.get(`http://localhost:5000/orders/${id}`);
        setOrderData(response.data);
      } catch (err) {
        console.error("Error fetching order details:", err);
        setError("❌ Failed to fetch order details");
      } finally {
        setLoading(false);
      }
    };

    const fetchAllOrders = async () => {
      try {
        const response = await axios.get("http://localhost:5000/orders");
        setAllOrders(response.data);
      } catch (err) {
        console.error("Error fetching all orders:", err);
      }
    };

    if (id) fetchOrderDetails();
    fetchAllOrders(); // Fetch all orders
  }, [id]);

  // Handle form input changes
  const handleChange = (e) => {
    const { name, value } = e.target;
    setOrderData((prevData) => ({
      ...prevData,
      [name]: value,
    }));
  };

  // Update order data in the backend
  const updateOrder = async (e) => {
    e.preventDefault();
    try {
      const response = await axios.put(`http://localhost:5000/orders/${id}`, orderData);
      
      if (response.status === 200) {
        setOrdersChanged((prev) => !prev);
        alert("✅ Order Updated Successfully!");
        navigate("/all-orders");
      } else {
        alert("⚠ Something went wrong. Please try again.");
      }
    } catch (err) {
      console.error("Update Error:", err);
      alert("❌ Failed to update order. Please try again.");
    }
  };

  if (loading) return <div>Loading...</div>;
  if (error) return <div style={{ color: "red", textAlign: "center" }}>{error}</div>;

  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        minHeight: "100vh",
        backgroundColor: "#f0f0f0",
        backgroundImage: `url(${backgroundImage})`,
        backgroundSize: "cover",
        backgroundRepeat: "no-repeat",
        backgroundBlendMode: "multiply",
      }}
    >
      {/* Update Form */}
      <div
        style={{
          backgroundColor: "rgba(255, 255, 255, 0.8)",
          padding: "25px",
          borderRadius: "10px",
          boxShadow: "0px 4px 10px rgba(0, 0, 0, 0.1)",
          width: "100%",
          maxWidth: "600px",
          marginBottom: "20px",
        }}
      >
        <h2 style={{ color: "#8B0000", fontWeight: "bold", textAlign: "center", marginBottom: "20px" }}>
          Update Order
        </h2>
        <form onSubmit={updateOrder} style={{ width: "100%" }}>
          {Object.keys(orderData).map((field) => (
            <div key={field} style={{ marginBottom: "15px" }}>
              <label
                htmlFor={field}
                style={{
                  display: "block",
                  fontWeight: "bold",
                  marginBottom: "5px",
                }}
              >
                {field.replace(/([A-Z])/g, " $1").trim()}
              </label>
              <input
                type="text"
                id={field}
                name={field}
                style={{
                  width: "100%",
                  padding: "10px",
                  border: "1px solid #ccc",
                  borderRadius: "5px",
                  boxSizing: "border-box",
                }}
                placeholder={`Enter ${field}`}
                value={orderData[field] || ""}
                onChange={handleChange}
                required
              />
            </div>
          ))}

          <div style={{ display: "flex", justifyContent: "space-between" }}>
            <button
              type="submit"
              style={{
                backgroundColor: "#b30000",
                color: "white",
                padding: "10px 20px",
                border: "none",
                borderRadius: "5px",
                cursor: "pointer",
                fontSize: "16px",
                width: "48%",
              }}
            >
              Update Order
            </button>
            <button
              type="button"
              onClick={() => navigate("/all-orders")}
              style={{
                backgroundColor: "#6c757d",
                color: "white",
                padding: "10px 20px",
                border: "none",
                borderRadius: "5px",
                cursor: "pointer",
                fontSize: "16px",
                width: "48%",
              }}
            >
              Cancel
            </button>
          </div>
        </form>
      </div>

      {/* All Orders List */}
      <div
        style={{
          backgroundColor: "white",
          padding: "20px",
          borderRadius: "10px",
          boxShadow: "0px 4px 10px rgba(0, 0, 0, 0.1)",
          width: "90%",
          maxWidth: "800px",
        }}
      >
        <h3 style={{ textAlign: "center", marginBottom: "15px" }}>📦 All Orders</h3>
        <table style={{ width: "100%", borderCollapse: "collapse" }}>
          <thead>
            <tr style={{ backgroundColor: "#8B0000", color: "white" }}>
              <th style={{ padding: "10px", border: "1px solid #ddd" }}>Order ID</th>
              <th style={{ padding: "10px", border: "1px solid #ddd" }}>Customer</th>
              <th style={{ padding: "10px", border: "1px solid #ddd" }}>Status</th>
            </tr>
          </thead>
          <tbody>
            {allOrders.map((order) => (
              <tr key={order.id} style={{ backgroundColor: "#f9f9f9", textAlign: "center" }}>
                <td style={{ padding: "10px", border: "1px solid #ddd" }}>{order.orderId}</td>
                <td style={{ padding: "10px", border: "1px solid #ddd" }}>
                  {order.firstName} {order.lastName}
                </td>
                <td style={{ padding: "10px", border: "1px solid #ddd" }}>{order.orderStatus}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default UpdateOrder;
